void sms_select_phone_num_select_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_sms_select_phone_num_obj_t * p_screen_param;
    lv_obj_t *      list = get_sms_select_phone_num_select_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param  = (ui_screen_sms_select_phone_num_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
#ifndef UI_DISPLAY_SPEED
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,1);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,1);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

#else

        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                pre_focus_obj       = lv_obj_get_child(list,child_id);
                lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                if (child_id != 0) {
                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    phonebook_map_node_t *p_cur_node;
                    get_focus_obj = lv_obj_get_child(list, child_id);
                    p_cur_node = lv_obj_get_user_data(get_focus_obj);
                    
                    if((int)p_cur_node==1){
                        p_cur_node = get_phonebook_prev_count_node(get_phonebook_tail_node(),PHONE_LIST_COUNT-1);
                        if(p_cur_node==NULL){
                            //p_cur_node=get_phonebook_head_node();
                        }
                        
                        if(p_screen_param->phonebook_count+1>PHONE_LIST_COUNT)
                            p_screen_param->list_first_index    = p_screen_param->phonebook_count+1-PHONE_LIST_COUNT;
                        else
                            p_screen_param->list_first_index    = 0;
            
                        
                        p_screen_param->p_list_first_node   = p_cur_node;
                        ui_screen_phone_list_sms_select_create(p_screen_param,p_screen_param->obj_list,p_cur_node);
            
                        child_cnt = lv_obj_get_child_cnt(list);
                        
                        pre_focus_obj = lv_obj_get_child(list, 0);                      
                        get_focus_obj = lv_obj_get_child(list, child_cnt-1);                    
                        lv_obj_add_state(get_focus_obj, LV_STATE_FOCUSED);
                    }else{
                        if(p_cur_node==get_phonebook_head_node()){
                            p_cur_node = NULL;
                        }
                        else{
                            p_cur_node = get_phonebook_prev_node(p_cur_node);
                        }
                        
                        p_screen_param->p_list_first_node   = p_cur_node;
                        if(p_screen_param->list_first_index>0)
                            p_screen_param->list_first_index--;
                        ui_screen_phone_list_sms_select_create(p_screen_param,p_screen_param->obj_list,p_cur_node);
            
            
                        pre_focus_obj = lv_obj_get_child(list, 1);                      
                        get_focus_obj = lv_obj_get_child(list, 0);                  
                        lv_obj_add_state(get_focus_obj, LV_STATE_FOCUSED);
                        
                    }
                }
                label = lv_obj_get_child(pre_focus_obj, 1);
                lv_label_set_long_mode(label ,LV_LABEL_LONG_CLIP);
            
                label = lv_obj_get_child(get_focus_obj, 1);
                lv_label_set_long_mode(label ,LV_LABEL_LONG_SCROLL); 
            
                child_id = get_list_child_focused_id(list,child_cnt);
            
                uint32_t per = (p_screen_param->list_first_index+child_id)*(100)/(p_screen_param->phonebook_count);
                per = per*(100-p_screen_param->bar_high)/100;
                per = 100-per;
                lv_bar_set_start_value(p_screen_param->bar,per-p_screen_param->bar_high,LV_ANIM_OFF);   
                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
            
                
                app_fp_play_tts_phonebook(lv_label_get_text(label));
            }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                pre_focus_obj       = lv_obj_get_child(list,child_id);
                lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                if (child_id != child_cnt - 1) {
                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    phonebook_map_node_t *p_cur_node;
                    get_focus_obj = lv_obj_get_child(list, child_id);
                    p_cur_node = lv_obj_get_user_data(get_focus_obj);   
                    if(p_cur_node==get_phonebook_tail_node()){
                        p_cur_node = NULL;
                        p_screen_param->p_list_first_node   = p_cur_node;
                        p_screen_param->list_first_index    = 0;
                        ui_screen_phone_list_sms_select_create(p_screen_param,p_screen_param->obj_list,p_cur_node);
            
                        child_cnt = lv_obj_get_child_cnt(list);
                        pre_focus_obj = lv_obj_get_child(list, 1);                      
                        get_focus_obj = lv_obj_get_child(list, 0);                  
                        lv_obj_add_state(get_focus_obj, LV_STATE_FOCUSED);
                    }else{
                        get_focus_obj = lv_obj_get_child(list, 1);
                        p_cur_node = lv_obj_get_user_data(get_focus_obj);
            
                        p_screen_param->p_list_first_node   = p_cur_node;
                        if(p_screen_param->list_first_index<p_screen_param->phonebook_count+1)
                                p_screen_param->list_first_index++;
                        ui_screen_phone_list_sms_select_create(p_screen_param,p_screen_param->obj_list,p_cur_node);
            
            
                        child_cnt = lv_obj_get_child_cnt(list);
                        pre_focus_obj = lv_obj_get_child(list, child_cnt-2);                        
                        get_focus_obj = lv_obj_get_child(list, child_cnt-1);                    
                        lv_obj_add_state(get_focus_obj, LV_STATE_FOCUSED);
            
                    }
                    
                }
            
                label = lv_obj_get_child(pre_focus_obj, 1);
                lv_label_set_long_mode(label ,LV_LABEL_LONG_CLIP);
            
                label = lv_obj_get_child(get_focus_obj, 1);
                lv_label_set_long_mode(label ,LV_LABEL_LONG_SCROLL); 
            
                child_id = get_list_child_focused_id(list,child_cnt);
            
                uint32_t per = (p_screen_param->list_first_index+child_id)*(100)/(p_screen_param->phonebook_count);
                per = per*(100-p_screen_param->bar_high)/100;
                per = 100-per;
            
                
                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
                lv_bar_set_start_value(p_screen_param->bar,per-p_screen_param->bar_high,LV_ANIM_OFF);   
                lv_bar_set_value(p_screen_param->bar,per,LV_ANIM_OFF);
            
                
                app_fp_play_tts_phonebook(lv_label_get_text(label));
            
            }
            break;

#endif

        case APP_KEY_VALUE_TOP_LEFT:
            {

                    if(p_screen_param->select_count>0){
                        //sms_send_select_phone_remind_screen(ui_Screen);
                        sms_send_remind_ui_enter_param_t enter_param;
                        enter_param.p_content   = p_screen_param->ui_enter_param->p_content;
                        enter_param.p_node      = (void **)(&p_screen_param->p_state[1]);
                        enter_param.node_count  = p_screen_param->phonebook_count;
                        enter_param.select_count= p_screen_param->select_count;
                        alv_am_win_enter(NULL,"sms_send_remind",&enter_param);
                    }
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
#ifndef UI_DISPLAY_SPEED
            {
                lv_obj_t *      obj_img;
                void *          p_node;

                if (p_screen_param->phonebook_count == 0)
                    return;

                if (child_id == 0) {
                    if (p_screen_param->p_state[child_id]) {
                        for (int i = 0; i < child_cnt; i++) {
                            get_focus_obj       = lv_obj_get_child(list,i);
                            obj_img             = lv_obj_get_child(get_focus_obj,0);
                            p_node              = (int) lv_obj_get_user_data(get_focus_obj);

                            p_screen_param->p_state[i] = 0;
                            lv_img_set_src(obj_img,ui_imgset_select[0]);
                            }

                        p_screen_param->select_count = 0;
                        }
                    else {
                        for (int i = 0; i < child_cnt; i++) {
                            get_focus_obj       = lv_obj_get_child(list,i);
                            obj_img             = lv_obj_get_child(get_focus_obj,0);
                            p_node              = (int) lv_obj_get_user_data(get_focus_obj);

                            p_screen_param->p_state[i] = p_node;
                            lv_img_set_src(obj_img,ui_imgset_select[1]);
                            }

                        p_screen_param->select_count = child_cnt - 1;
                        }
                    }
                else {
                    get_focus_obj       = lv_obj_get_child(list,child_id);
                    obj_img             = lv_obj_get_child(get_focus_obj,0);
                    p_node              = (int) lv_obj_get_user_data(get_focus_obj);


                    if (p_screen_param->p_state[child_id]) {
                        p_screen_param->p_state[child_id] = 0;
                        lv_img_set_src(obj_img,ui_imgset_select[0]);

                        if (p_screen_param->select_count)
                            p_screen_param->select_count--;

                        }
                    else {
                        p_screen_param->p_state[child_id] = p_node;
                        lv_img_set_src(obj_img,ui_imgset_select[1]);

                        if (p_screen_param->select_count < child_cnt - 1)
                            p_screen_param->select_count++;
                        }
                    }

                }

#else

            {
                lv_obj_t *      obj_img;
                void *          p_node;

                        if((child_id==0)&&(p_screen_param->list_first_index==0))
                        {
                            if(p_screen_param->phonebook_count>SMS_SEND_PHPONE_NUM_COUNT_MAX){
                                sms_select_phone_num_select_count_remind();
                                break;
                            }
                        
                            if(p_screen_param->p_state[child_id])
                            {
                                for(int i=0;i<child_cnt;i++)
                                {
                                    get_focus_obj   = lv_obj_get_child(list, i);
                                    obj_img         = lv_obj_get_child(get_focus_obj, 0);
            
                                    lv_img_set_src(obj_img, ui_imgset_select[0]);
                                }
                                for(int i=0;i<p_screen_param->phonebook_count+1;i++)
                                {
                                    p_screen_param->p_state[i] = 0;                 
                                }
                                p_screen_param->select_count = 0;
                            }
                            else
                            {
                                for(int i=0;i<child_cnt;i++)
                                {
                                    get_focus_obj   = lv_obj_get_child(list, i);
                                    obj_img         = lv_obj_get_child(get_focus_obj, 0);
            
                                    lv_img_set_src(obj_img, ui_imgset_select[1]);
                                }
            
                                p_screen_param->p_state[0] = (phonebook_map_node_t *)1;
                                {
                                    phonebook_map_node_t *p_cur_node;
                                    p_cur_node = get_phonebook_head_node();
                                    for(int i=0;i<p_screen_param->phonebook_count;i++)
                                    {
                                        p_screen_param->p_state[i+1] = p_cur_node;  
            
                                        p_cur_node = get_phonebook_next_node(p_cur_node);
                                        if(p_cur_node==NULL)
                                            break;
                                    }
                                }
            
                                
                                p_screen_param->select_count = p_screen_param->phonebook_count;
                            }
                            
                        }
                        else{
                            uint32_t index;
                            get_focus_obj   = lv_obj_get_child(list, child_id);
                            obj_img         = lv_obj_get_child(get_focus_obj, 0);
                            p_node          = (void *)lv_obj_get_user_data(get_focus_obj);
                            index           = p_screen_param->list_first_index+child_id;
                            if(p_screen_param->p_state[index])
                            {
                                p_screen_param->p_state[index] = 0;
                                lv_img_set_src(obj_img, ui_imgset_select[0]);
                                if(p_screen_param->select_count)
                                    p_screen_param->select_count--;

                                //if(p_screen_param->select_count==0){
                                if (p_screen_param->p_state[0]) {
                                    if (p_screen_param->list_first_index == 0) {
                                        get_focus_obj       = lv_obj_get_child(list,0);
                                        obj_img             = lv_obj_get_child(get_focus_obj,0);

                                        lv_img_set_src(obj_img,ui_imgset_select[0]);
                                        }
                                    p_screen_param->p_state[0] = 0;
                                    }
                                //}

                            }
                            else
                            {
                                if(p_screen_param->select_count+1>SMS_SEND_PHPONE_NUM_COUNT_MAX){
                                    sms_select_phone_num_select_count_remind();
                                    break;
                                }
                                p_screen_param->p_state[index] = p_node;
                                lv_img_set_src(obj_img, ui_imgset_select[1]);
            
                                if(p_screen_param->select_count<p_screen_param->phonebook_count)
                                    p_screen_param->select_count++;
                                if(p_screen_param->select_count==p_screen_param->phonebook_count){
                                    if(p_screen_param->p_state[0]==0){
                                        if(p_screen_param->list_first_index==0){
                                            get_focus_obj   = lv_obj_get_child(list, 0);
                                            obj_img         = lv_obj_get_child(get_focus_obj, 0);
                                            lv_img_set_src(obj_img, ui_imgset_select[1]);
                                        }
                                        p_screen_param->p_state[0] = (phonebook_map_node_t *)1; 
                                    }
                                }

                            }
                        }
                    }
#endif

            break;

        case LV_KEY_END:
            {
                alv_am_app_exit_action_all();
                }
            break;

        default:
            break;
        }

}


static void remind_timer_callback_sms_send_ui_exit(screen_remind_param_t * p_param)
{

    alv_am_win_exit_action(NULL,"write",NULL);
    alv_am_win_exit_action(NULL,"write_option",NULL);
    alv_am_win_exit_action(NULL,"send_option",NULL);
    alv_am_win_exit_action(NULL,"select_phone_num",NULL);
}


typedef struct {
    int32_t         result;
    void *          user_data;
} sms_send_result_t;

static int32_t sms_send_phone_select_result_callback(void * p_param,uint32_t size)
{
    screen_remind_param_t screen_remind_param;
    sms_send_result_t * p_sms_send_result;
    lv_obj_t *      ui_screen;

    p_sms_send_result   = p_param;
    ui_screen_remind_param_init(&screen_remind_param);

    if (p_sms_send_result->result == 0)
        screen_remind_param.str = "短信已发送";
    else 
        screen_remind_param.str = "短信发送失败,请重新尝试";

    screen_remind_param.tiemr_delay = 1500;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_sms_send_ui_exit;
    screen_remind_param.user_data = NULL;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    lv_disp_load_scr(ui_screen);

    return 0;
}



static int32_t sms_send_select_func_callback_result(int32_t send_result,void * user_data)
{
    sms_send_result_t sms_send_result;

    sms_send_result.result = send_result;
    sms_send_result.user_data = user_data;

    app_msg_send_callback(sms_send_phone_select_result_callback,&sms_send_result,sizeof(sms_send_result_t));
    return 0;
}



static void remind_timer_callback_sms_send_select_phone_failed(screen_remind_param_t * p_param)
{
    screen_remind_param_t screen_remind_param;
    lv_obj_t *      ui_screen;

    ui_screen_remind_param_init(&screen_remind_param);


    screen_remind_param.str = "短信发送失败,请重新尝试";

    screen_remind_param.tiemr_delay = 1500;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_sms_send_ui_exit;
    screen_remind_param.user_data = NULL;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    lv_disp_load_scr(ui_screen);

}


static void sms_send_select_phone_num(lv_obj_t * ui_Screen)
{
    ui_screen_sms_select_phone_num_obj_t * p_screen_param;
    phonebook_param_t phonebook_param;
    char *          text;

    p_screen_param  = (ui_screen_sms_select_phone_num_obj_t *) lv_obj_get_user_data(ui_Screen);

    tele_sms_data_set_send_fun_callback(sms_send_select_func_callback_result,ui_Screen);

    text                = p_screen_param->ui_enter_param->p_content;

    for (int i = 1; i < p_screen_param->state_count; i++) {
        memset(&phonebook_param,0,sizeof(phonebook_param_t));

        if (p_screen_param->p_state[i]) {
            read_phonebook_param_storge(p_screen_param->p_state[i],&phonebook_param);

            if (strlen(phonebook_param.number) > 0)
                tele_sms_data_send(text,phonebook_param.number,phonebook_param.name,false);
            }
        }
}


void sms_send_select_phone_remind_screen(lv_obj_t * ui_Screen)
{
    ui_screen_sms_select_phone_num_obj_t * p_screen_param;
    screen_remind_param_t screen_remind_param;
    lv_obj_t *      ui_screen;
    uint8_t         cur_card_id = TS_CARD_ID_MAX;

    p_screen_param  = (ui_screen_sms_select_phone_num_obj_t *) lv_obj_get_user_data(ui_Screen);

    aic_srv_tele_sim_get_current_card(&cur_card_id);
    sprintf(p_screen_param->remind_str,"卡%d正在发送短信",(int) (1 + cur_card_id));

    ui_screen_remind_param_init(&screen_remind_param);
    screen_remind_param.str = p_screen_param->remind_str;


    screen_remind_param.tiemr_delay = 10000;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_sms_send_select_phone_failed;
    screen_remind_param.user_data = ui_Screen;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    lv_disp_load_scr(ui_screen);

    sms_send_select_phone_num(ui_Screen);

}



